// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {W_WALLET, Log} from "../src/W_WALLET.sol";

contract InvMutTest is Test {
    W_WALLET c;
    function setUp() public { c = new W_WALLET(address(new Log())); }

    function testFuzz_property(uint256 amountA, uint256 amountB, address actor) public {
        vm.assume(actor != address(0));
        amountA = bound(amountA, 1, 100 ether);
        amountB = bound(amountB, 1, 100 ether);

        vm.deal(actor, amountA + amountB);
        vm.prank(actor);
        c.Put{value: amountA}(0);
        vm.prank(actor);
        c.Put{value: amountB}(0);

        // Rule: deposits accumulate; balance after two deposits is amountA + amountB.
        (, uint256 bal) = c.Acc(actor);
        assertTrue(bal == amountA + amountB);
    }
}
